"""cam_studio.cam.grain — Траектории чистовой обработки с учетом направления волокон древесины."""

import math
from typing import List, Tuple


def generate_grain_toolpaths(bbox: Tuple[float, float, float, float], grain_angle_deg: float,
                             stepover_mm: float, climb_only: bool = True) -> List[List[Tuple[float, float]]]:
    """
    Генерирует параллельные проходы чистовой выборки, строго ориентированные по направлению волокон.
    climb_only=True гарантирует однонаправленное попутное фрезерование (исключает tear-out на обратном ходе).
    """
    min_x, min_y, max_x, max_y = bbox
    cx = (min_x + max_x) / 2.0
    cy = (min_y + max_y) / 2.0
    diag = math.hypot(max_x - min_x, max_y - min_y) * 1.2

    theta = math.radians(grain_angle_deg)
    cos_t = math.cos(theta)
    sin_t = math.sin(theta)

    # Нормаль к волокнам
    norm_x = -sin_t
    norm_y = cos_t

    # Вектор вдоль волокон
    dir_x = cos_t
    dir_y = sin_t

    half_diag = diag / 2.0
    num_passes = int(math.ceil(diag / stepover_mm))

    passes = []
    start_offset = -half_diag

    for i in range(num_passes + 1):
        offset = start_offset + i * stepover_mm
        # Базовая точка на оси нормали
        bx = cx + norm_x * offset
        by = cy + norm_y * offset

        p_start = (bx - dir_x * half_diag, by - dir_y * half_diag)
        p_end = (bx + dir_x * half_diag, by + dir_y * half_diag)

        if not climb_only and (i % 2 == 1):
            passes.append([p_end, p_start])
        else:
            passes.append([p_start, p_end])

    return passes
